class HwInfo(GenericTabular):
    """Hwinfo command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Hwinfo command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(HwInfo, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.repeat = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "hw_info"
        return cmd

    def _parse_line_to_current_result(self, line):
        key = self._set_key(line)
        if key != "":
            if key in self.current_ret["dict"]:
                if key in self.repeat:
                    self.repeat[key] += 1
                else:
                    self.repeat[key] = 0
                key = f"{key}_{self.repeat[key]}"

            self.current_ret["dict"][key] = {}
            row_dict = dict(zip(self.headers, line))
            self.current_ret["dict"][key].update(row_dict)
            self.current_ret["list"].append(row_dict)
        else:
            self._add_line_to_previous_row(line)


